        return []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    visited = set()
    queue = [(start[0], start[1], [start])]

    while queue:
        r, c, path = queue.pop(0)
        if (r, c) == goal:
            return path
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                queue.append((nr, nc, path + [(nr, nc)]))

    return []
